WFJ.Data.add("book", {
  ["b204e62e797e64aa"] = { "Sebbene la ribellione fosse stata sedata, l'⟦Horde=Orda⟧ non riuscì a rimediare alle terribili perdite subite. Il tradimento di Gul'dan aveva dato all'⟦Alliance=Alleanza⟧ non solo speranza, ma anche il tempo di riorganizzarsi e di contrattaccare.", "." },
  ["b23b123d6683439b"] = { "Rimasta sola a proteggere Kalimdor dai pericoli del nuovo mondo, Tyrande radunò una potente forza combattente tra le sue sorelle elfe della notte. Le impavide guerriere, addestratissime, che giurarono di difendere Kalimdor divennero note come le ⟦Sentinels=Sentinelle⟧. Benché preferissero pattugliare da sole le foreste ombrose di ⟦Ashenvale=Valtetra⟧, potevano contare su molti alleati in caso di necessità.", "." },
  ["b273a25f1c67e404"] = { "era Asterion, che viveva tra la gente di ⟦Bashal'Aran=Bashal'aran⟧ e si recava spesso ad ⟦Ameth'Aran=Ameth'aran⟧ per provvedere ai bisogni e ai desideri del suo popolo.\n\nE così, sulle rive del ⟦Well of Eternity=Pozzo dell'Eternità⟧, le città gemelle crebbero e prosperarono, mentre il mondo sotto le stelle scivolava lentamente nella follia.", "." },
  ["b2afd52ea2a83439"] = { "⟦Goodsteel's Balanced Flameberge=Spada di Fuoco Bilanciata di Ferrofiz⟧ -\n\nInfine, voglio indietro uno dei migliori lavori di forgiatura che abbia mai fatto. Questa flamberga era una spada incredibile, che avevo donato a quello che credevo un guerriero grande e onorevole. Be', si è fatto suonare da un murloc di nome Jarquai? Una cosa del genere.\n\nStava viaggiando lungo la costa della ⟦Swamp of Sorrows=Palude del Dolore⟧ quando gli è venuto in mente di attaccare la creatura. Ha fallito e, a quanto pare, è fuggito, non prima però di aver lasciato l'arma lì, alla mercé del murloc.", "." },
  ["b2f321c296ff4ff6"] = { "⟦Essence of the Exile=Essenza dell'Esiliato⟧:\n\nQuesta essenza si ottiene fondendo i tre talismani degli elementali esiliati degli ⟦Arathi Highlands=Altopiani d'Arathi⟧. Raccogli dagli elementali i Talismani del Tuono, del Fuoco e dell'Acqua, poi metti otto talismani di ciascun tipo nel mio calderone.\n\nDai talismani si formerà l'essenza dell'esiliato.", "." },
})
